typedef long long ll;

typedef struct {
    int x, y, id;
} Point;

static int cmp_x(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return p->id - q->id;
}

static int cmp_y(const void *a, const void *b) {
    const Point *p = (const Point *)a;
    const Point *q = (const Point *)b;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    return p->id - q->id;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *pts = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &pts[i].x, &pts[i].y);
        pts[i].id = i;
    }

    /*
      Two cities are directly movable between if one is strictly lower-left
      of the other, i.e. x and y are both smaller (or both larger in reverse).

      Reachability through repeated moves forms connected components in the
      comparability graph of the 2D partial order.

      A standard property here:
      If we sort by x, whenever the maximum y seen so far is greater than the
      minimum y in the suffix, then some pair across the cut is incomparable,
      so components cannot be separated there. Otherwise, all left points have
      y < all right points, hence every left point is lower-left of every right
      point, so the graph connects across the cut.

      Therefore connected components are exactly maximal blocks in x-sorted
      order where for every internal cut:
          prefix_max_y > suffix_min_y
      and a new component starts when:
          prefix_max_y < suffix_min_y
      (strict because coordinates for movement are strict).
    */

    qsort(pts, N, sizeof(Point), cmp_x);

    int *suffixMin = (int *)malloc(sizeof(int) * N);
    suffixMin[N - 1] = pts[N - 1].y;
    for (int i = N - 2; i >= 0; i--) {
        suffixMin[i] = (pts[i].y < suffixMin[i + 1]) ? pts[i].y : suffixMin[i + 1];
    }

    int *ans = (int *)malloc(sizeof(int) * N);

    int start = 0;
    int prefMax = pts[0].y;
    for (int i = 0; i < N - 1; i++) {
        if (pts[i].y > prefMax) prefMax = pts[i].y;

        if (prefMax < suffixMin[i + 1]) {
            int sz = i - start + 1;
            for (int j = start; j <= i; j++) ans[pts[j].id] = sz;
            start = i + 1;
            if (start < N) prefMax = pts[start].y;
        }
    }

    int sz = N - start;
    for (int j = start; j < N; j++) ans[pts[j].id] = sz;

    for (int i = 0; i < N; i++) {
        printf("%d\n", ans[i]);
    }

    free(pts);
    free(suffixMin);
    free(ans);
    return 0;
}

