    vector<int> bit(M + 2, 0);

    auto add = [&](int idx, int val) {
        while (idx <= M) {
            bit[idx] += val;
            idx += idx & -idx;
        }
    };

    auto sum = [&](int idx) {
        int res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    };

    // Count lower-left reachable (including itself)
    vector<int> lowerLeft(N);
    for (int i = 0; i < N; i++) {
        int yIdx = getYIdx(cities[i].y);
        lowerLeft[cities[i].idx] = sum(yIdx); // cities with x < current and y <= current
