        int total = sum(M);
        upperRight[cities[i].idx] = total - sum(yIdx - 1);
        add(yIdx, 1);
    }

    // Answer = lowerLeft + upperRight - 1 (since counted twice)
    for (int i = 0; i < N; i++) {
        cout << lowerLeft[i] + upperRight[i] - 1 << "\n";
    }

    return 0;
}

