    }

    sort(a.begin(), a.end(), [](const City& A, const City& B) {
        if (A.x != B.x) return A.x < B.x;
        return A.y < B.y;
    });

    struct Group {
        long long x;
        long long mnY, mxY;
        int l, r; // indices in sorted city array [l, r]
        int cnt;
    };

    vector<Group> groups;
    for (int i = 0; i < N; ) {
        int j = i;
        long long x = a[i].x;
        long long mnY = a[i].y, mxY = a[i].y;
        while (j < N && a[j].x == x) {
            mnY = min(mnY, a[j].y);
            mxY = max(mxY, a[j].y);
            ++j;
        }
        groups.push_back({x, mnY, mxY, i, j - 1, j - i});
        i = j;
    }

    int G = (int)groups.size();
    vector<long long> prefMin(G), suffMax(G);
    for (int i = 0; i < G; ++i) {
        prefMin[i] = groups[i].mnY;
        if (i) prefMin[i] = min(prefMin[i], prefMin[i - 1]);
    }
    for (int i = G - 1; i >= 0; --i) {
        suffMax[i] = groups[i].mxY;
        if (i + 1 < G) suffMax[i] = max(suffMax[i], suffMax[i + 1]);
    }

    vector<int> ans(N);
    int start = 0;
    while (start < G) {
        int end = start;
        while (end + 1 < G && !(prefMin[end] >= suffMax[end + 1])) {
            ++end;
        }
        int compSize = 0;
        for (int g = start; g <= end; ++g) compSize += groups[g].cnt;
        for (int g = start; g <= end; ++g) {
            for (int i = groups[g].l; i <= groups[g].r; ++i) {
                ans[a[i].idx] = compSize;
            }
        }
        start = end + 1;
    }

