import sys
sys.setrecursionlimit(1 << 20)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    cities = []
    idx = 1
    for i in range(n):
        x = int(input_data[idx]); y = int(input_data[idx+1])
        idx += 2
        cities.append((x, y, i))

    # Sort by x, then y
    cities.sort(key=lambda p: (p[0], p[1]))

    dsu = DSU(n)

    # Connect consecutive cities if y is increasing (reachable upper-right chain)
    for i in range(1, n):
        if cities[i][1] >= cities[i-1][1]:
            dsu.union(cities[i][2], cities[i-1][2])

    # Sort by y, then x to connect lower-left direction
    cities.sort(key=lambda p: (p[1], p[0]))
    for i in range(1, n):
        if cities[i][0] >= cities[i-1][0]:
            dsu.union(cities[i][2], cities[i-1][2])

    # Output sizes
    out = []
    for i in range(n):
        out.append(str(dsu.size[dsu.find(i)]))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

