    for x, y, i in comp:
        by_x[x].append((y, i))

    # DSU
    parent = list(range(n))
    size = [1] * n

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    # Sweep left -> right:
    # if there exists a previous point with smaller x and smaller y,
    # connect current point to one representative among such points.
    bit = [0] * (maxy + 2)
    rep = [-1] * (maxy + 2)

    def bit_update(pos, val_y, idx):
        while pos <= maxy:
            if val_y > bit[pos]:
                bit[pos] = val_y
                rep[pos] = idx
            pos += pos & -pos

    def bit_query(pos):
        best_y = 0
        best_idx = -1
        while pos > 0:
            if bit[pos] > best_y:
                best_y = bit[pos]
                best_idx = rep[pos]
            pos -= pos & -pos
        return best_idx

    for x in range(1, maxx + 1):
        # Query first, update later to enforce strictly smaller x
        for y, idx in by_x[x]:
            j = bit_query(y - 1)  # strictly smaller y
            if j != -1:
