        // BIT for countGE (process in reverse)
        Arrays.fill(bit, 0);
        int[] countGE = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int p = order[i];
            int yIdx = comp.get(points[p][1]);
            countGE[p] = queryRange(bit, yIdx, idx);
            update(bit, yIdx, 1);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(countLE[i] + countGE[i] + 1).append("\n");
        }
        System.out.print(sb);
    }

    static void update(int[] bit, int idx, int val) {
        while (idx < bit.length) {
            bit[idx] += val;
            idx += idx & -idx;
        }
    }

    static int query(int[] bit, int idx) {
        int sum = 0;
        while (idx > 0) {
            sum += bit[idx];
            idx -= idx & -idx;
        }
        return sum;
    }

    static int queryRange(int[] bit, int l, int r) {
        return query(bit, r) - query(bit, l - 1);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static int[] parent, size;
    static int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
    static void union(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) { int t = a; a = b; b = t; }
        parent[b] = a; size[a] += size[b];
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[][] cities = new int[n][3];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            cities[i][0] = Integer.parseInt(st.nextToken());
            cities[i][1] = Integer.parseInt(st.nextToken());
            cities[i][2] = i;
        }
        Arrays.sort(cities, (a, b) -> a[0] - b[0]);
        parent = new int[n]; size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        int maxY = cities[0][1], maxYIdx = 0;
        for (int i = 1; i < n; i++) {
            if (cities[i][1] < maxY) { union(cities[i][2], cities[maxYIdx][2]); }
            if (cities[i][1] > maxY) { maxY = cities[i][1]; maxYIdx = i; }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(size[find(i)]).append('\n');
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/*
We have N cities with coordinates (x, y).
From city A, you can move to city B iff:
- xB < xA and yB < yA   (lower-left), or
- xB > xA and yB > yA   (upper-right)

This means movement is possible exactly between comparable points under the partial order
defined by both coordinates increasing together.

For each city, we need the size of its connected component in the undirected graph where
an edge exists between two cities if one is strictly lower-left of the other.

Key fact:
If we sort by x, then cities in the same connected component form a contiguous block where,
inside that block, consecutive cities (by x) have non-decreasing y after sorting by x.
More precisely, after sorting by x (and y as tie-breaker), whenever between adjacent cities
we have y[i] > y[i+1], no edge can cross this boundary, so components split there.
If y[i] <= y[i+1], those two cities are directly connected (since x strictly increases unless
same x; with same x they are not directly connected, but same-x cities also cannot connect
through points across a decreasing boundary incorrectly due to strict x condition).

However, equal x needs care: cities with same x cannot connect directly to each other.
To handle strict x properly, process groups of equal x:
Let prefMaxY over previous x-groups and suffMinY over next x-groups.
A city/group can connect to previous side iff some previous point has smaller y,
and to next side iff some next point has larger y.
This yields component boundaries between consecutive x-groups:
boundary between group g and g+1 is disconnected iff
maxY among groups <= g  >=  minY among groups >= g+1
Actually if left prefix maxY < right suffix minY, there exists full comparability bridge.
But for connectivity across the boundary, it is enough that some left point and some right point
satisfy y_left < y_right, i.e. min right > some left value. Since x strictly increases across groups,
the existence of any such pair connects the two sides.
Equivalent boundary is disconnected iff all left y >= all right y, i.e.
minLeft? No, need no pair y_left < y_right, meaning max right <= min left? That's too strong.
Condition "for all left,right: y_left >= y_right" is equivalent minLeft >= maxRight.

So we need whether there exists at least one left-right comparable pair.
That exists iff minLeft < maxRight.

Thus maintain prefix minimum on left and suffix maximum on right over y-values by x-groups.
Boundary is connected iff prefixMinLeft < suffixMaxRight.

Then x-groups between disconnected boundaries form components. Any city in those groups has
the same answer = total number of cities in that component.

Proof:
If boundary connected, there is an edge between some left city and some right city, merging components.
If boundary disconnected, every left city has y >= every right city, so no cross-boundary edge/path exists,
because any path crossing would need at least one edge between a left-group city and right-group city.

Complexities: O(N log N).
*/

public class Main {
    static class City {
        int x, y, idx;
        City(int x, int y, int idx) {
            this.x = x;
            this.y = y;
            this.idx = idx;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        City[] a = new City[N];
        for (int i = 0; i < N; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            a[i] = new City(x, y, i);
        }

        Arrays.sort(a, (p, q) -> {
            if (p.x != q.x) return Integer.compare(p.x, q.x);
            return Integer.compare(p.y, q.y);
        });

        // Build groups of equal x
        ArrayList<Integer> gStart = new ArrayList<>();
        ArrayList<Integer> gEnd = new ArrayList<>();
        ArrayList<Integer> gMinY = new ArrayList<>();
        ArrayList<Integer> gMaxY = new ArrayList<>();
        ArrayList<Integer> gSize = new ArrayList<>();

        int i = 0;
        while (i < N) {
            int j = i;
            int minY = a[i].y, maxY = a[i].y;
            while (j < N && a[j].x == a[i].x) {
                minY = Math.min(minY, a[j].y);
                maxY = Math.max(maxY, a[j].y);
                j++;
            }
            gStart.add(i);
            gEnd.add(j - 1);
            gMinY.add(minY);
            gMaxY.add(maxY);
            gSize.add(j - i);
            i = j;
        }

        int G = gStart.size();

        int[] prefMin = new int[G];
        int[] suffMax = new int[G];

        for (i = 0; i < G; i++) {
            if (i == 0) prefMin[i] = gMinY.get(i);
            else prefMin[i] = Math.min(prefMin[i - 1], gMinY.get(i));
        }
        for (i = G - 1; i >= 0; i--) {
            if (i == G - 1) suffMax[i] = gMaxY.get(i);
            else suffMax[i] = Math.max(suffMax[i + 1], gMaxY.get(i));
        }

        int[] groupCompSize = new int[G];
        int compStart = 0;
        int compCount = gSize.get(0);

        for (i = 0; i < G - 1; i++) {
            boolean connectedAcross = prefMin[i] < suffMax[i + 1];
            if (connectedAcross) {
                compCount += gSize.get(i + 1);
            } else {
                for (int g = compStart; g <= i; g++) groupCompSize[g] = compCount;
                compStart = i + 1;
                compCount = gSize.get(i + 1);
            }
        }
        for (int g = compStart; g < G; g++) groupCompSize[g] = compCount;

        int[] ans = new int[N];
        for (i = 0; i < G; i++) {
            for (int p = gStart.get(i); p <= gEnd.get(i); p++) {
                ans[a[p].idx] = groupCompSize[i];
            }
        }

        StringBuilder sb = new StringBuilder();
        for (i = 0; i < N; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
